(()=>{if(window.__hsjBuscaAgendamentos20261023)return;window.__hsjBuscaAgendamentos20261023=true;
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','"':'&quot;'}[c]));
let type='consulta',selected=null;
window.hsjOpenAppointmentSearch=function(kind){type=kind;selected=null;document.getElementById('modal').innerHTML='<div class="back"><div class="modal" style="max-width:850px"><div class="mh"><b>🔎 Buscar paciente — Agendamento de '+(kind==='cirurgia'?'Cirurgia':'Consulta')+'</b><button class="btn" onclick="document.getElementById(\'modal\').innerHTML=\'\'">Fechar</button></div><div class="mb"><div class="field"><label>Nome, CPF ou IDS</label><input id="hsjSearchAppointmentInput" placeholder="Digite o nome, CPF ou IDS" oninput="hsjFindAppointmentPatient()"></div><div class="notice">Selecione um cadastro existente. A pesquisa não cria outro cadastro do mesmo paciente.</div><div id="hsjSearchAppointmentResults"></div></div><div class="mf"><button class="btn primary" id="hsjSearchAppointmentContinue" onclick="hsjContinueAppointment()" disabled>Continuar com paciente selecionado</button></div></div></div>';document.getElementById('hsjSearchAppointmentInput').focus();};
window.hsjFindAppointmentPatient=function(){const q=document.getElementById('hsjSearchAppointmentInput')?.value.trim().toLowerCase()||'',results=document.getElementById('hsjSearchAppointmentResults');if(!results)return;selected=null;document.getElementById('hsjSearchAppointmentContinue').disabled=true;if(q.length<2){results.innerHTML='<p class="sub">Digite pelo menos dois caracteres.</p>';return;}const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const matched=S.rows.filter(x=>x.active!==false&&[x.patient_name,x.cpf,x.ids].some(v=>norm(v).includes(norm(q)))).slice(0,40);results.innerHTML='<div class="tablewrap"><table class="table" style="min-width:640px"><thead><tr><th></th><th>PACIENTE</th><th>CPF</th><th>IDS</th><th>ETAPA</th><th>PROCEDIMENTO</th></tr></thead><tbody>'+matched.map(x=>'<tr><td><input type="radio" name="hsjAppointmentChoice" value="'+x.id+'" onchange="hsjSelectAppointmentPatient(this.value)"></td><td>'+safe(x.patient_name)+'</td><td>'+safe(x.cpf||'—')+'</td><td>'+safe(x.ids||'—')+'</td><td>'+safe(labels[x.stage]||x.stage)+'</td><td>'+safe(x.procedure_name||'—')+'</td></tr>').join('')+'</tbody></table></div>'+(matched.length===0?'<p>Nenhum cadastro localizado. Utilize a opção existente “Paciente sem cadastro em fila” se realmente for um novo paciente.</p>':'');};
window.hsjSelectAppointmentPatient=function(id){selected=id;document.getElementById('hsjSearchAppointmentContinue').disabled=false;};
window.hsjContinueAppointment=function(){const x=S.rows.find(r=>r.id===selected);if(!x)return alert('Selecione um paciente válido.');if(type==='cirurgia'){if(x.stage==='concluida')return alert('Este atendimento já teve a jornada concluída.');return window.hsjAgendaSurgery(x.id)}return window.editConsult(x.id)};
const old=window.renderConsult;
window.renderConsult=function(){const result=old.apply(this,arguments);const head=document.querySelector('#content .section-head');if(!head||head.querySelector('[data-hsj-appointment-search]'))return result;const wrap=document.createElement('div');wrap.dataset.hsjAppointmentSearch='1';wrap.className='map-modes';wrap.innerHTML='<button class="btn primary" onclick="hsjOpenAppointmentSearch(\'consulta\')">🔎 Agendar consulta — buscar paciente</button><button class="btn green" onclick="hsjOpenAppointmentSearch(\'cirurgia\')">🔎 Agendar cirurgia — buscar paciente</button>';head.appendChild(wrap);return result;};
if(S.view==='consulta_preop')renderConsult();
})();